import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.B8TleWq7.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function n(r,e,l,s,c,h){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Current version: <strong>0.5.1</strong>. This page is generated from <code>CHANGELOG.md</code> in the Keel repo by <code>npm run gen:changelog</code>; edit that file, not this one.</p><h2 id="_0-5-1" tabindex="-1">0.5.1 <a class="header-anchor" href="#_0-5-1" aria-label="Permalink to &quot;0.5.1&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong><code>vault-notes</code>: topic hubs.</strong> The about-10 KB split now applies to a note in any folder, not only <code>Systems/</code>: it splits into a subfolder with a small topic hub (a table of its part notes), and new part notes get their row in that hub. A part note is linked only from its topic hub; <code>Start Here.md</code> links the hub once and no longer repeats its parts.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong><code>/next-system</code> finds lettered steps.</strong> <code>context.js</code> read &quot;step 14g&quot; as step 14 and printed &quot;No step 14 heading found&quot;. It now matches a <code>### Step 14g:</code> heading, and a lettered part with no heading of its own (&quot;step 15a&quot; inside step 15) falls back to its number&#39;s section.</li></ul><h2 id="_0-5-0" tabindex="-1">0.5.0 <a class="header-anchor" href="#_0-5-0" aria-label="Permalink to &quot;0.5.0&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>The game&#39;s working-loop skills ship with Keel:</strong> <code>/next-system</code> (with <code>context.js</code>, which now finds build orders in subfolders), <code>/next-design</code>, <code>/next-brainstorm</code> and <code>/idea</code>. They read the vault layout from <code>Starter/Docs/</code>.</li><li><strong><code>tag-check</code> hook</strong> (<code>.claude/hooks/tag-check.js</code>, before every Bash/PowerShell command): refuses a <code>git tag</code> that creates a tag without a description, and gives the <code>git tag -a &amp;lt;tag&gt; -m &quot;...&quot;</code> form to use.</li><li><strong>Docs site:</strong> a &quot;Notes and Claude&quot; guide (the vault layout, how notes stay current, the working loop, every skill and hook).</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Every tag needs a description.</strong> The &quot;Publish docs&quot; workflow refuses a lightweight tag or an empty description, and uses the description as the published docs commit&#39;s message.</li><li>Keel&#39;s own <code>CLAUDE.md</code> is slimmed like the starter&#39;s: the vault rules point to the <code>vault-notes</code> skill.</li><li><code>/idea</code> takes the brainstorm note format from <code>design-talk</code> instead of repeating it.</li></ul><h3 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>Existing games: <code>update</code> brings the new skills and hook. If the game had its own copies of <code>idea</code>, <code>next-system</code>, <code>next-design</code> or <code>next-brainstorm</code>, <code>update</code> replaces them with Keel&#39;s. Register the hook yourself (starter files are never re-copied): add a <code>PreToolUse</code> entry with matcher <code>Bash|PowerShell</code> running <code>node &quot;$CLAUDE_PROJECT_DIR/.claude/hooks/tag-check.js&quot;</code> to <code>.claude/settings.json</code>.</li></ul><h2 id="_0-4-0" tabindex="-1">0.4.0 <a class="header-anchor" href="#_0-4-0" aria-label="Permalink to &quot;0.4.0&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong><code>docs-check</code> Stop hook</strong> (<code>.claude/hooks/docs-check.js</code>): when Claude ends a turn, flags uncommitted <code>src/</code> files whose <code>Systems/</code> notes are older than the code, or that no note lists, in one line, once.</li><li><strong><code>vault-notes</code> skill</strong>: the vault rules (where notes go, keeping them small and current) and the step close after a build step passes its check.</li><li><strong><code>design-talk</code> skill</strong>: routes game-design talk to <code>Design/</code>, <code>Brainstorm/</code> or chat; brainstorm note format and promotion.</li><li><strong>Vault skeleton</strong> in <code>Starter/Docs/</code> (starter files, copied once by <code>new</code>): <code>Done.md</code>, <code>Look Later.md</code>, <code>Design/</code> (<code>Design Index</code>, <code>Design Status</code>, <code>System Spec Template</code>), <code>Brainstorm/Brainstorm Status.md</code>, <code>Systems/</code> (<code>Game Already Exists</code>, <code>Game Tooling</code>). Empty tables and headings: the one layout every Keel game shares.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Starter <code>Status.md</code> is Current / Last / Next only; finished work goes to <code>Done.md</code>, open decisions to <code>Look Later.md</code>.</li><li>Starter <code>CLAUDE.md</code> is about a third of its old size: the vault and design rules moved into the two skills, the layout rules into <code>luau-layout</code>. It no longer tells a game to add rows to Keel&#39;s read-only <code>Already Exists.md</code> (the game&#39;s own is <code>Game Already Exists.md</code>).</li><li><code>/verify</code> step 2 checks Status against the git log and <code>Done.md</code> (Current, Last and its date, Next; Last is <code>Done.md</code>&#39;s last row).</li><li><code>.gitignore</code> ignores <code>Docs/Completed Build Orders/</code>.</li></ul><h3 id="migration-1" tabindex="-1">Migration <a class="header-anchor" href="#migration-1" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>Existing games: <code>update</code> adds the hook, the two skills and the new <code>/verify</code>. Starter files are never copied by <code>update</code>, so register the hook yourself: add a <code>Stop</code> entry running <code>node &quot;$CLAUDE_PROJECT_DIR/.claude/hooks/docs-check.js&quot;</code> to <code>.claude/settings.json</code>. Copy any skeleton notes you lack from <code>Starter/Docs/</code>. A game whose <code>CLAUDE.md</code> holds the vault rules can drop them in favour of the skills.</li></ul><h2 id="_0-3-2" tabindex="-1">0.3.2 <a class="header-anchor" href="#_0-3-2" aria-label="Permalink to &quot;0.3.2&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The <code>note-lookup</code> hook&#39;s header comment pointed at <code>Docs/Systems/Tooling.md</code>, which in a game is <code>Docs/Systems/Keel/Tooling.md</code>; it now names both (comment only, no behaviour change).</li></ul><h3 id="migration-2" tabindex="-1">Migration <a class="header-anchor" href="#migration-2" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None.</li></ul><h2 id="_0-3-1" tabindex="-1">0.3.1 <a class="header-anchor" href="#_0-3-1" aria-label="Permalink to &quot;0.3.1&quot;">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Release process only (no Luau changed): every version stays a Git tag, and only a <strong>major</strong> version (<code>v1.0.0</code>, <code>v2.0.0</code>, ...) also gets a GitHub Release. A new workflow, &quot;Release (majors only)&quot;, creates it when the tag is pushed, with notes from this changelog (the major&#39;s Migration first, then everything since the previous major). Minors, patches and every <code>0.x</code> version stay tags only. See the Releasing Keel guide.</li></ul><h3 id="migration-3" tabindex="-1">Migration <a class="header-anchor" href="#migration-3" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. <code>keel.js</code> still installs from tags; nothing in a game changes.</li></ul><h2 id="_0-3-0" tabindex="-1">0.3.0 <a class="header-anchor" href="#_0-3-0" aria-label="Permalink to &quot;0.3.0&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Frame hooks.</strong> Any Service, Controller or System can define <code>PreSimulation(dt)</code> (every frame, before physics: for velocities and forces physics must see this frame) and <code>PreRender(dt)</code> (every frame, just before drawing, client only: for the camera). The Loader hands them to the Scheduler when Start returns, like <code>Update</code>. They get the same protection as <code>Update</code>: guarded, slow calls logged, and a hook that waits is stopped. Unity&#39;s closest are <code>FixedUpdate</code> and <code>LateUpdate</code>, but Roblox has no fixed step: <code>dt</code> is the frame&#39;s real time.</li><li><code>Scheduler.AddFrame(module, &quot;PreSimulation&quot; | &quot;PreRender&quot;)</code>. Game code rarely calls it; the Loader does.</li><li><code>Types.Module</code> has the two optional fields.</li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><code>Scheduler.Remove(module)</code> stops every hook of the module, not only <code>Update</code>.</li><li>Scheduler log lines name the hook (<code>Name.PreSimulation: …</code>); <code>Update</code> lines read as before.</li><li>The Loader stops the boot if a module&#39;s <code>PreSimulation</code> or <code>PreRender</code> isn&#39;t a function, or if a server module has a <code>PreRender</code> (there is no rendering on the server).</li></ul><h3 id="migration-4" tabindex="-1">Migration <a class="header-anchor" href="#migration-4" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. Modules without the new hooks behave exactly as before. A module that connects its own <code>RunService.PreSimulation</code> or <code>PreRender</code> can move that code into the matching method to get the Scheduler&#39;s guard and logging.</li></ul><h2 id="_0-2-3" tabindex="-1">0.2.3 <a class="header-anchor" href="#_0-2-3" aria-label="Permalink to &quot;0.2.3&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>LogOff</code> understands <code>*</code> (mute every tag) and <code>-Name</code> (exempt one tag from <code>*</code>): <code>*,-Replica</code> mutes everything except <code>Replica</code>.</li><li><code>Log.Only(tag)</code> writes that for you. <code>Log.Set(&#39;*&#39;, enabled)</code> mutes or restores all tags.</li><li>Console: <code>log &amp;lt;tag&gt; only</code> mutes every other tag, and <code>log * off</code> / <code>log * on</code> mute or restore everything. The tag argument autocompletes <code>*</code>.</li></ul><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>The <code>log</code> command&#39;s reply lists the <code>LogOff</code> entries now set (for example <code>LogOff: *, -Replica</code>) instead of <code>muted: ...</code>.</li></ul><h3 id="migration-5" tabindex="-1">Migration <a class="header-anchor" href="#migration-5" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. An existing <code>LogOff</code> value such as <code>Data,Replica</code> works as before.</li></ul><h2 id="_0-2-2" tabindex="-1">0.2.2 <a class="header-anchor" href="#_0-2-2" aria-label="Permalink to &quot;0.2.2&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><code>keel.js update</code> no longer deletes and recreates the owned folders (<code>Keel</code>, <code>KeelServer</code>, ...). It overwrites files in place, deletes only files Keel dropped (and folders left empty), so Studio&#39;s Script Sync stays connected and you no longer reconnect after an update.</li></ul><h3 id="migration-6" tabindex="-1">Migration <a class="header-anchor" href="#migration-6" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>The update <em>to</em> 0.2.2 still runs the old <code>keel.js</code>, so reconnect Script Sync on <code>Keel</code> and <code>KeelServer</code> once after it. Updates after that keep the connection.</li></ul><h2 id="_0-2-1" tabindex="-1">0.2.1 <a class="header-anchor" href="#_0-2-1" aria-label="Permalink to &quot;0.2.1&quot;">​</a></h2><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Docs only: the Replica and State note records that the two-player privacy check passed live (a client reads other players&#39; <code>Public</code> state and <code>nil</code> for their <code>Owner</code> state; right after joining it reads <code>nil</code> until the snapshot arrives, so use <code>State.Observe</code>). No code changed.</li></ul><h3 id="migration-7" tabindex="-1">Migration <a class="header-anchor" href="#migration-7" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None.</li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Keel Setup</strong>, a Studio plugin (<code>tools/KeelSetup.lua</code>, an owned file) that creates the six root Folders and the optional place attributes, and lists the Script Sync connects still to make. Studio cannot script the connect itself, and a template place file does not keep the connections, so the connects stay manual.</li><li><code>keel.js new</code> prints the plugin install step and the next steps in Studio.</li><li>A documentation site in <code>site/</code> (VitePress): getting started, tutorials, guides, an API reference generated from the source, and a changelog page. Not copied into games.</li></ul><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Releasing now requires every change to be documented in the same release, with deprecations, new features and kits recorded in the changelog (see <code>site/guides/releasing-keel.md</code>).</li></ul><h3 id="migration-8" tabindex="-1">Migration <a class="header-anchor" href="#migration-8" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><ul><li>None. After <code>node tools/keel.js update v0.2.0</code> a game has <code>tools/KeelSetup.lua</code>; copy it into Studio&#39;s Plugins folder if you want the plugin.</li></ul><h2 id="_0-1-1" tabindex="-1">0.1.1 <a class="header-anchor" href="#_0-1-1" aria-label="Permalink to &quot;0.1.1&quot;">​</a></h2><p><code>keel.js</code> writes text files with LF line endings (a Windows clone had CRLF, which StyLua rejected). New games get a <code>.gitattributes</code> that keeps LF on checkout.</p><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><p>First version. Extracted from StealTheGun (commit <code>7831be3</code>): Loader, Scheduler, Signal, Trove, Log, Net (Packet), Defs, Entity, Data (ProfileStore), State and Replica, Client layer (Input, UIController, View, Widget), Console (Cmdr), Purchases, Policy, LiveDefs, the unit test runner and its specs, plus the starter game files, tooling and notes.</p>',66)])])}const m=o(i,[["render",n]]);export{g as __pageData,m as default};
